  1	//! Command-line argument handling matching the C runtime's `std::atoi`.
  2	
  3	/// `std::atoi` semantics as implemented by glibc, i.e. `(int) strtol(s, NULL, 10)`:
  4	///
  5	/// * leading whitespace is skipped,
  6	/// * an optional `+`/`-` sign is consumed,
  7	/// * digits are consumed greedily and parsing stops at the first non-digit,
  8	/// * input with no leading digits yields `0`,
  9	/// * out-of-range values saturate at the `long` bounds and are then truncated to
 10	///   `int`.
 11	pub fn atoi(s: &str) -> i32 {
 12	    let bytes = s.as_bytes();
 13	    let mut i = 0;
 14	
 15	    // isspace(): space, \t, \n, \v, \f, \r
 16	    while i < bytes.len() && matches!(bytes[i], b' ' | b'\t' | b'\n' | 0x0b | 0x0c | b'\r') {
 17	        i += 1;
 18	    }
 19	
 20	    let negative = match bytes.get(i) {
 21	        Some(b'-') => {
 22	            i += 1;
 23	            true
 24	        }
 25	        Some(b'+') => {
 26	            i += 1;
 27	            false
 28	        }
 29	        _ => false,
 30	    };
 31	
 32	    let mut acc: i64 = 0;
 33	    let mut overflowed = false;
 34	    while i < bytes.len() && bytes[i].is_ascii_digit() {
 35	        let digit = i64::from(bytes[i] - b'0');
 36	        match acc.checked_mul(10).and_then(|v| v.checked_add(digit)) {
 37	            Some(v) => acc = v,
 38	            None => overflowed = true,
 39	        }
 40	        i += 1;
 41	    }
 42	
 43	    let long_value = if overflowed {
 44	        if negative {
 45	            i64::MIN
 46	        } else {
 47	            i64::MAX
 48	        }
 49	    } else if negative {
 50	        -acc
 51	    } else {
 52	        acc
 53	    };
 54	
 55	    long_value as i32
 56	}
 57	//! Generation of the Archimedean spiral ring fed to the triangulator.
 58	
 59	use std::f64::consts::PI;
 60	
 61	/// Sample `2 * n` points of a spiral whose radius grows linearly with the
 62	/// parameter `t` over two full turns.
 63	///
 64	/// The arithmetic mirrors the C++ source term by term — `t` is the integer ratio
 65	/// `i / (n * 2)` and the angle is `(4.0 * PI) * t` — so the sampled coordinates
 66	/// are bit-identical doubles.
 67	pub fn spiral(n: i32) -> Vec<[f64; 2]> {
 68	    let count = n.wrapping_mul(2);
 69	    let mut points: Vec<[f64; 2]> = Vec::new();
 70	
 71	    let mut i: i32 = 0;
 72	    while i < count {
 73	        let t = f64::from(i) / f64::from(count);
 74	        let radius = t;
 75	        let angle = 4.0 * PI * t;
 76	        points.push([radius * angle.cos(), radius * angle.sin()]);
 77	        i += 1;
 78	    }
 79	
 80	    points
 81	}
