 46	    /// For collinear points `p`, `q`, `r`, check if point `q` lies on segment `pr`.
 47	    pub(super) fn on_segment(&self, p: usize, q: usize, r: usize) -> bool {
 48	        let (p, q, r) = (&self.nodes[p], &self.nodes[q], &self.nodes[r]);
 49	        q.x <= p.x.max(r.x) && q.x >= p.x.min(r.x) && q.y <= p.y.max(r.y) && q.y >= p.y.min(r.y)
 50	    }
 51	
 52	    /// Check if two segments intersect.
 53	    pub(super) fn intersects(&self, p1: usize, q1: usize, p2: usize, q2: usize) -> bool {
 54	        let o1 = Self::sign(self.area(p1, q1, p2));
 55	        let o2 = Self::sign(self.area(p1, q1, q2));
 56	        let o3 = Self::sign(self.area(p2, q2, p1));
 57	        let o4 = Self::sign(self.area(p2, q2, q1));
 58	
 59	        if o1 != o2 && o3 != o4 {
 60	            return true; // general case
 61	        }
 62	
 63	        // p1, q1 and p2 are collinear and p2 lies on p1q1
 64	        if o1 == 0 && self.on_segment(p1, p2, q1) {
 65	            return true;
 66	        }
 67	        // p1, q1 and q2 are collinear and q2 lies on p1q1
 68	        if o2 == 0 && self.on_segment(p1, q2, q1) {
 69	            return true;
 70	        }
 71	        // p2, q2 and p1 are collinear and p1 lies on p2q2
 72	        if o3 == 0 && self.on_segment(p2, p1, q2) {
 73	            return true;
 74	        }
 75	        // p2, q2 and q1 are collinear and q1 lies on p2q2
 76	        if o4 == 0 && self.on_segment(p2, q1, q2) {
 77	            return true;
 78	        }
 79	
 80	        false
 81	    }
