162	    /// Whether sector in vertex `m` contains the sector in vertex `p` in the same
163	    /// coordinates.
164	    pub(super) fn sector_contains_sector(&self, m: usize, p: usize) -> bool {
165	        let mp = self.nodes[m].prev;
166	        let pn = self.nodes[p].next;
167	        self.area(mp, m, p) < 0.0 && self.area(pn, m, mp) < 0.0
168	    }
