143	    /// Create a circular doubly-linked list from polygon points in the specified
144	    /// winding order.
145	    fn linked_list(&mut self, points: &[[f64; 2]], clockwise: bool) -> usize {
146	        let mut sum = 0.0;
147	        let len = points.len();
148	        let mut last = NIL;
149	
150	        // calculate original winding order of a polygon ring
151	        let mut j = if len > 0 { len - 1 } else { 0 };
152	        for i in 0..len {
153	            let p1 = &points[i];
154	            let p2 = &points[j];
155	            let p20 = p2[0];
156	            let p10 = p1[0];
157	            let p11 = p1[1];
158	            let p21 = p2[1];
159	            sum += (p20 - p10) * (p11 + p21);
160	            j = i;
161	        }
162	
163	        // link points into circular doubly-linked list in the specified winding order
164	        if clockwise == (sum > 0.0) {
165	            for i in 0..len {
166	                last = self.insert_node(self.vertices + i, &points[i], last);
167	            }
168	        } else {
169	            for i in (0..len).rev() {
170	                last = self.insert_node(self.vertices + i, &points[i], last);
171	            }
172	        }
173	
174	        if last != NIL {
175	            let next = self.nodes[last].next;
176	            if self.equals(last, next) {
177	                self.remove_node(last);
178	                last = next;
179	            }
180	        }
181	
182	        self.vertices += len;
183	
184	        last
185	    }
